entries.answer:
Most már tisztán értem — te egy **teljesen saját Zig stacket** építesz (saját tensor, saját GPU dispatch, saját minden), és erre akarod 0-ról megírni az LLM tréning optimizer kernelt B200-ra. Nem kell sem Futhark, sem Bend, sem PyTorch. Adjuk végig a teljes képet.

***

## A B200 hardver — amire tervezel

A B200 compute capability **10.0 (sm\_100)**, 228 KB shared memory per SM, 64K 32-bites regiszter per SM.  A memória sávszélesség 8 TB/s HBM3e, 192 GB kapacitással.  Az optimizer step (Adam, Muon, SOAP, bármi) szinte kizárólag **memory-bound**: a B200-on az optimizer frissítés sebességét az határozza meg, mennyire hatékonyan éred el a HBM-et, nem a compute. Ez azt jelenti, hogy a kernel design lényege: **kevés pass, nagy koaleszált olvasás/írás, semmi fölösleges HBM round-trip**.[1][2]

***

## GPU dispatch Zig-ből CUDA nélkül

Zig-ből három reális úton érsz el GPU-t a B200-on CUDA toolkit nélkül:[3]

**1. LLVM NVPTX backend (Zig → PTX):** A Zig LLVM-en keresztül tud `nvptx64-nvidia-cuda` targetra fordítani, ami PTX assembleyt generál. Ezt a PTX-et a **CUDA Driver API** (`libcuda.so`) tölti be és futtatja — ez NEM a CUDA toolkit, csak a driver sharedlib, ami minden NVIDIA driverrel együtt jár. Tehát: `zig build-obj -target nvptx64-nvidia-cuda -mcpu sm_100`, majd `cuModuleLoadData` + `cuLaunchKernel` Zig FFI-ből.[4][3]

**2. SPIR-V → Vulkan compute:** Zig SPIR-V backend érett állapotban van OpenCL/Vulkan számára.  Zig GPU kódot fordítasz SPIR-V-re, Vulkan compute pipeline-ként töltöd be, és `vkCmdDispatch`-el indítod. Vulkan 2-4× lassabb lehet CUDA-nál optimizer kernelekre, de teljes independence CUDA-tól.[5][3]

**3. SPIR-V → OpenCL:** Az NVIDIA OpenCL ICD driver megvan minden modern driverben, és SPIR-V kernelt is elfogad. OpenCL-ben pointer aritmetika engedélyezett (szemben Vulkan baseline-nal), és a `work_group_reduce_add` beépített kollektív műveletek adottak.[6]

A legpraktikusabb B200-ra 0-ról: **NVPTX (1. opció)**, mert pontosan `sm_100`-ra tuning-olhatsz, és a CUDA Driver API egyetlen `.so` dependency.

***

## A B200 sm\_100 PTX-specifikus részletek

A B200 PTX ISA 8.x-et használ. Amit a saját kerneleidben ki kell használni: a `ld.global.nc` (non-coherent/read-only cache), a `st.global.cs` (cache streaming hint, jelzi hogy nem kell L2-ben tartani), és a `.bf16` típusú aritmetika natívan elérhető PTX-ben `add.bf16`, `mul.bf16` utasításokkal.  Az optimizer state-et (momentum, variance vektorok) mindig **bf16** vagy **fp32** formátumban érdemes tartani — a B200 FP4/FP8 Tensor Core-jai elsősorban a forward/backward GEMM-ekhez valók, az optimizer step skalár műveletek bf16/fp32-vel futnak.[7][1]

***

## Zig kernel struktúra — PTX-re fordítható optimizer

Ez az a Zig kódrészlet, ami `nvptx64-nvidia-cuda` targetra fordul, vagyis a Zig compiler NVPTX IR-t generál belőle, amit PTX-re fordít az LLVM backend. A GPU-specifikus beépítetteket (`@as`, adresszterek, thread index) Zig-ben inline assembly vagy `@import("std").Target`-specifikus builtinekkel éred el:

```zig
// optimizer_kernel.zig
// fordítás: zig build-obj -target nvptx64-nvidia-cuda -mcpu sm_100

const std = @import("std");

// PTX thread index builtins Zig NVPTX backenden
extern fn @"llvm.nvvm.read.ptx.sreg.tid.x"() callconv(.C) i32;
extern fn @"llvm.nvvm.read.ptx.sreg.ntid.x"() callconv(.C) i32;
extern fn @"llvm.nvvm.read.ptx.sreg.ctaid.x"() callconv(.C) i32;

inline fn threadId() i32 {
    return @"llvm.nvvm.read.ptx.sreg.tid.x"();
}
inline fn blockDim() i32 {
    return @"llvm.nvvm.read.ptx.sreg.ntid.x"();
}
inline fn blockId() i32 {
    return @"llvm.nvvm.read.ptx.sreg.ctaid.x"();
}

// AdamW optimizer step kernel — minden szál egy paramétert kezel
// p, g, m, v: globális memóriában lévő f32 tömbök
// n: paraméterszám, t: lépésszám, lr/b1/b2/eps/wd: hiperparaméterek
export fn adamw_step_kernel(
    p: [*]f32,  // paraméter (R/W)
    g: [*]f32,  // gradiens (R)
    m: [*]f32,  // 1. momentum (R/W)
    v: [*]f32,  // 2. momentum (R/W)
    n: i32,
    t: i32,
    lr: f32,
    b1: f32,
    b2: f32,
    eps: f32,
    wd: f32,
) callconv(.PtxKernel) void {
    const idx = blockId() * blockDim() + threadId();
    if (idx >= n) return;

    const i: usize = @intCast(idx);

    const gi = g[i];
    const pi = p[i];
    const mi = m[i];
    const vi = v[i];

    // Momentum frissítés
    const m1 = b1 * mi + (1.0 - b1) * gi;
    const v1 = b2 * vi + (1.0 - b2) * gi * gi;

    // Bias korrekció
    const tf: f32 = @floatFromInt(t);
    const b1t = std.math.pow(f32, b1, tf);
    const b2t = std.math.pow(f32, b2, tf);
    const mhat = m1 / (1.0 - b1t);
    const vhat = v1 / (1.0 - b2t);

    // Paraméter frissítés + decoupled weight decay
    const p1 = pi - lr * (mhat / (@sqrt(vhat) + eps)) - lr * wd * pi;

    // Visszaírás
    m[i] = m1;
    v[i] = v1;
    p[i] = p1;
}
```

***

## Host oldal Zig-ben — CUDA Driver API FFI

A host oldalon a CUDA Driver API-t `extern` deklarációkkal hívod meg, nincs szükség semmi CUDA toolkit headerre:

```zig
// cuda_driver.zig — CUDA Driver API FFI Zig-ből
// csak libcuda.so kell, ami a driverrel együtt van

const std = @import("std");

pub const CUresult = i32;
pub const CUdeviceptr = u64;
pub const CUmodule = *anyopaque;
pub const CUfunction = *anyopaque;
pub const CUstream = *anyopaque;

extern "cuda" fn cuInit(flags: u32) callconv(.C) CUresult;
extern "cuda" fn cuDeviceGet(device: *i32, ordinal: i32) callconv(.C) CUresult;
extern "cuda" fn cuCtxCreate_v2(ctx: **anyopaque, flags: u32, dev: i32) callconv(.C) CUresult;
extern "cuda" fn cuMemAlloc_v2(dptr: *CUdeviceptr, bytesize: usize) callconv(.C) CUresult;
extern "cuda" fn cuMemcpyHtoD_v2(dst: CUdeviceptr, src: *const anyopaque, bytesize: usize) callconv(.C) CUresult;
extern "cuda" fn cuMemcpyDtoH_v2(dst: *anyopaque, src: CUdeviceptr, bytesize: usize) callconv(.C) CUresult;
extern "cuda" fn cuModuleLoadData(module: *CUmodule, image: *const anyopaque) callconv(.C) CUresult;
extern "cuda" fn cuModuleGetFunction(hfunc: *CUfunction, hmod: CUmodule, name: [*:0]const u8) callconv(.C) CUresult;
extern "cuda" fn cuLaunchKernel(
    f: CUfunction,
    gridDimX: u32, gridDimY: u32, gridDimZ: u32,
    blockDimX: u32, blockDimY: u32, blockDimZ: u32,
    sharedMemBytes: u32,
    hStream: ?CUstream,
    kernelParams: ?*?*anyopaque,
    extra: ?*?*anyopaque,
) callconv(.C) CUresult;
extern "cuda" fn cuStreamSynchronize(hStream: ?CUstream) callconv(.C) CUresult;

// PTX string beágyazása (fordításkor generált .ptx fájlból)
const OPTIMIZER_PTX = @embedFile("optimizer_kernel.ptx");

pub const OptimizerGPU = struct {
    mod: CUmodule,
    fn_adamw: CUfunction,
    p_dev: CUdeviceptr,
    m_dev: CUdeviceptr,
    v_dev: CUdeviceptr,
    n: usize,

    pub fn init(n: usize) !@This() {
        var mod: CUmodule = undefined;
        _ = cuModuleLoadData(&mod, OPTIMIZER_PTX.ptr);
        var fn_adamw: CUfunction = undefined;
        _ = cuModuleGetFunction(&fn_adamw, mod, "adamw_step_kernel");

        var p_dev: CUdeviceptr = 0;
        var m_dev: CUdeviceptr = 0;
        var v_dev: CUdeviceptr = 0;
        _ = cuMemAlloc_v2(&p_dev, n * @sizeOf(f32));
        _ = cuMemAlloc_v2(&m_dev, n * @sizeOf(f32));
        _ = cuMemAlloc_v2(&v_dev, n * @sizeOf(f32));

        return .{ .mod = mod, .fn_adamw = fn_adamw,
                  .p_dev = p_dev, .m_dev = m_dev, .v_dev = v_dev, .n = n };
    }

    pub fn step(self: *@This(), g_dev: CUdeviceptr, t: i32,
                lr: f32, b1: f32, b2: f32, eps: f32, wd: f32) void {
        const block_size: u32 = 512;
        const grid = (@as(u32, @intCast(self.n)) + block_size - 1) / block_size;

        // B200-on 512 szál/blokk jó alapértelmezett optimizer kernelhez
        // (memory-bound, nem compute-bound → nincs szükség maximális occupancy-ra)
        var args = [_]?*anyopaque{
            @ptrCast(&self.p_dev), @ptrCast(&g_dev),
            @ptrCast(&self.m_dev), @ptrCast(&self.v_dev),
            @ptrCast(&self.n),    @ptrCast(&t),
            @ptrCast(&lr),        @ptrCast(&b1),
            @ptrCast(&b2),        @ptrCast(&eps),
            @ptrCast(&wd),
        };
        _ = cuLaunchKernel(self.fn_adamw, grid, 1, 1, block_size, 1, 1, 0,
                            null, @ptrCast(&args), null);
    }
};
```

***

## BF16 optimizer state — B200 specifikus

Ha bf16 master weighteket tartasz (ami B200-on hatékony, mert a HBM-ből kevesebb bájtot kell olvasni), a kernel így néz ki bf16 paraméterre + fp32 momentumokra (mixed precision optimizer):

```zig
// BF16 paraméter + FP32 momentum (tipikus LLM tréning konfiguráció)
// bf16 = u16 bitcast, manuálisan konvertálunk f32 <-> bf16

inline fn bf16_to_f32(x: u16) f32 {
    // bf16 egyszerűen az f32 felső 16 bitje
    const bits: u32 = @as(u32, x) << 16;
    return @bitCast(bits);
}

inline fn f32_to_bf16(x: f32) u16 {
    // Round-to-nearest-even
    const bits: u32 = @bitCast(x);
    const rounding: u32 = (bits >> 16) & 1;
    return @intCast((bits + 0x7FFF + rounding) >> 16);
}

export fn adamw_bf16_kernel(
    p: [*]u16,   // bf16 paraméter
    g: [*]u16,   // bf16 gradiens
    m: [*]f32,   // fp32 1. momentum
    v: [*]f32,   // fp32 2. momentum
    n: i32,
    t: i32,
    lr: f32, b1: f32, b2: f32, eps: f32, wd: f32,
) callconv(.PtxKernel) void {
    const idx = blockId() * blockDim() + threadId();
    if (idx >= n) return;
    const i: usize = @intCast(idx);

    // BF16 → FP32 konverzió a számításhoz
    const gi = bf16_to_f32(g[i]);
    const pi = bf16_to_f32(p[i]);

    const m1 = b1 * m[i] + (1.0 - b1) * gi;
    const v1 = b2 * v[i] + (1.0 - b2) * gi * gi;

    const tf: f32 = @floatFromInt(t);
    const mhat = m1 / (1.0 - std.math.pow(f32, b1, tf));
    const vhat = v1 / (1.0 - std.math.pow(f32, b2, tf));

    const p1 = pi - lr * (mhat / (@sqrt(vhat) + eps)) - lr * wd * pi;

    m[i] = m1;
    v[i] = v1;
    p[i] = f32_to_bf16(p1);  // visszaírjuk bf16-ként
}
```

***

## Amit a saját stack architektúrájában figyelembe kell venned

Mivel minden saját, a legfontosabb döntési pont: a **tensor allokátor** és a **kernel dispatch** hogyan csatolódik egymáshoz. B200-on az optimizer state (m, v vektorok) és a paraméterek pontosan akkor kerülnek HBM-be, amikor allokálod őket — ha a saját tensor struktúrád nem tartja nyilván, hogy adott tömb melyik eszközön (host/device) van, akkor az optimizer step hívásakor felesleges memcpy-kat kockáztatsz.  A legjobb pattern: a `Tensor` típusod tartalmaz egy `device_ptr: ?CUdeviceptr` mezőt, és az optimizer step csak ezzel dolgozik, soha nem húz semmit vissza host-ra a lépés közben.[8]

A build.zig-ben a PTX-et két lépésben generálod: először `zig build-obj -target nvptx64-nvidia-cuda -mcpu sm_100 optimizer_kernel.zig -femit-llvm-ir`, majd az LLVM `llc` eszközzel PTX-re konvertálod, és `@embedFile`-lal beágyazod a host binárisba. Így az egész egy önálló bináris lesz, egyetlen `libcuda.so` runtime-dependency-vel.

Mit akarsz elsőként megírni: a dispatch layer-t (hogyan jutnak be a kernelek a GPU-ra), a tensor allokátort, vagy magát az optimizer logikát? Ehhez tudok konkrétabb Zig kódot küldeni.

```zig
const std = @import("std");

pub const CUresult = i32;
pub const CUdevice = i32;
pub const CUcontext = *anyopaque;
pub const CUmodule = *anyopaque;
pub const CUfunction = *anyopaque;
pub const CUdeviceptr = u64;
pub const CUstream = *anyopaque;

pub const CudaAPI = struct {
    lib: std.DynLib,
    cuInit: *const fn (u32) callconv(.C) CUresult,
    cuDeviceGet: *const fn (*CUdevice, i32) callconv(.C) CUresult,
    cuCtxCreate_v2: *const fn (*CUcontext, u32, CUdevice) callconv(.C) CUresult,
    cuMemAlloc_v2: *const fn (*CUdeviceptr, usize) callconv(.C) CUresult,
    cuMemFree_v2: *const fn (CUdeviceptr) callconv(.C) CUresult,
    cuMemcpyHtoD_v2: *const fn (CUdeviceptr, *const anyopaque, usize) callconv(.C) CUresult,
    cuMemcpyDtoH_v2: *const fn (*anyopaque, CUdeviceptr, usize) callconv(.C) CUresult,
    cuModuleLoadData: *const fn (*CUmodule, *const anyopaque) callconv(.C) CUresult,
    cuModuleGetFunction: *const fn (*CUfunction, CUmodule, [*:0]const u8) callconv(.C) CUresult,
    cuLaunchKernel: *const fn (CUfunction, u32, u32, u32, u32, u32, u32, u32, ?CUstream, ?[*] ?*anyopaque, ?[*] ?*anyopaque) callconv(.C) CUresult,
    cuCtxSynchronize: *const fn () callconv(.C) CUresult,

    pub fn load() !CudaAPI {
        var lib = std.DynLib.open("libcuda.so.1") catch return error.CudaLibraryNotFound;
        return CudaAPI{
            .lib = lib,
            .cuInit = lib.lookup(*const fn (u32) callconv(.C) CUresult, "cuInit") orelse return error.SymbolNotFound,
            .cuDeviceGet = lib.lookup(*const fn (*CUdevice, i32) callconv(.C) CUresult, "cuDeviceGet") orelse return error.SymbolNotFound,
            .cuCtxCreate_v2 = lib.lookup(*const fn (*CUcontext, u32, CUdevice) callconv(.C) CUresult, "cuCtxCreate_v2") orelse return error.SymbolNotFound,
            .cuMemAlloc_v2 = lib.lookup(*const fn (*CUdeviceptr, usize) callconv(.C) CUresult, "cuMemAlloc_v2") orelse return error.SymbolNotFound,
            .cuMemFree_v2 = lib.lookup(*const fn (CUdeviceptr) callconv(.C) CUresult, "cuMemFree_v2") orelse return error.SymbolNotFound,
            .cuMemcpyHtoD_v2 = lib.lookup(*const fn (CUdeviceptr, *const anyopaque, usize) callconv(.C) CUresult, "cuMemcpyHtoD_v2") orelse return error.SymbolNotFound,
            .cuMemcpyDtoH_v2 = lib.lookup(*const fn (*anyopaque, CUdeviceptr, usize) callconv(.C) CUresult, "cuMemcpyDtoH_v2") orelse return error.SymbolNotFound,
            .cuModuleLoadData = lib.lookup(*const fn (*CUmodule, *const anyopaque) callconv(.C) CUresult, "cuModuleLoadData") orelse return error.SymbolNotFound,
            .cuModuleGetFunction = lib.lookup(*const fn (*CUfunction, CUmodule, [*:0]const u8) callconv(.C) CUresult, "cuModuleGetFunction") orelse return error.SymbolNotFound,
            .cuLaunchKernel = lib.lookup(*const fn (CUfunction, u32, u32, u32, u32, u32, u32, u32, ?CUstream, ?[*] ?*anyopaque, ?[*] ?*anyopaque) callconv(.C) CUresult, "cuLaunchKernel") orelse return error.SymbolNotFound,
            .cuCtxSynchronize = lib.lookup(*const fn () callconv(.C) CUresult, "cuCtxSynchronize") orelse return error.SymbolNotFound,
        };
    }
};

pub const Tensor = struct {
    api: *const CudaAPI,
    data_host: []f32,
    data_device: CUdeviceptr,
    size: usize,

    pub fn init(allocator: std.mem.Allocator, api: *const CudaAPI, size: usize) !Tensor {
        const data_host = try allocator.alloc(f32, size);
        @memset(data_host, 0.0);
        var data_device: CUdeviceptr = 0;
        const res = api.cuMemAlloc_v2(&data_device, size * @sizeOf(f32));
        if (res != 0) return error.CudaAllocFailed;
        return Tensor{
            .api = api,
            .data_host = data_host,
            .data_device = data_device,
            .size = size,
        };
    }

    pub fn deinit(self: *Tensor, allocator: std.mem.Allocator) void {
        _ = self.api.cuMemFree_v2(self.data_device);
        allocator.free(self.data_host);
    }

    pub fn toDevice(self: *Tensor) !void {
        const res = self.api.cuMemcpyHtoD_v2(self.data_device, self.data_host.ptr, self.size * @sizeOf(f32));
        if (res != 0) return error.CudaMemcpyFailed;
    }

    pub fn toHost(self: *Tensor) !void {
        const res = self.api.cuMemcpyDtoH_v2(self.data_host.ptr, self.data_device, self.size * @sizeOf(f32));
        if (res != 0) return error.CudaMemcpyFailed;
    }
};

