pub const AdamW = struct {
    api: *const CudaAPI,
    module: CUmodule,
    kernel: CUfunction,
    t: u32,
    lr: f32,
    b1: f32,
    b2: f32,
    eps: f32,
    wd: f32,

    pub fn init(api: *const CudaAPI, lr: f32, b1: f32, b2: f32, eps: f32, wd: f32) !AdamW {
        var module: CUmodule = undefined;
        const res_load = api.cuModuleLoadData(&module, ptx_source.ptr);
        if (res_load != 0) return error.CudaModuleLoadFailed;

        var kernel: CUfunction = undefined;
        const res_func = api.cuModuleGetFunction(&kernel, module, "adamw_f32");
        if (res_func != 0) return error.CudaGetFunctionFailed;

        return AdamW{
            .api = api,
            .module = module,
            .kernel = kernel,
            .t = 0,
            .lr = lr,
            .b1 = b1,
            .b2 = b2,
            .eps = eps,
            .wd = wd,
        };
    }

    pub fn step(self: *AdamW, p: *Tensor, g: *Tensor, m: *Tensor, v: *Tensor) !void {
        self.t += 1;
        const b1t = std.math.pow(f32, self.b1, @floatFromInt(self.t));
        const b2t = std.math.pow(f32, self.b2, @floatFromInt(self.t));

        const block_size: u32 = 512;
        const n: u32 = @intCast(p.size);
        const grid_size: u32 = (n + block_size - 1) / block_size;

        var args = [_]?*anyopaque{
            @ptrCast(&p.data_device),
            @ptrCast(&g.data_device),
            @ptrCast(&m.data_device),
            @ptrCast(&v.data_device),
            @ptrCast(&n),
            @ptrCast(&self.lr),
            @ptrCast(&self.b1),
            @ptrCast(&self.b2),
            @ptrCast(&b1t),
            @ptrCast(&b2t),
            @ptrCast(&self.eps),
            @ptrCast(&self.wd),
        };

        const res = self.api.cuLaunchKernel(
            self.kernel,
            grid_size, 1, 1,
            block_size, 1, 1,
            0,
            null,
            @ptrCast(&args),
            null,
        );
        if (res != 0) return error.CudaLaunchFailed;

        const sync_res = self.api.cuCtxSynchronize();
        if (sync_res != 0) return error.CudaSyncFailed;
    }
};

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var api = try CudaAPI.load();
    defer api.lib.close();

    if (api.cuInit(0) != 0) return error.CudaInitFailed;

    var device: CUdevice = undefined;
    if (api.cuDeviceGet(&device, 0) != 0) return error.CudaDeviceFailed;

    var context: CUcontext = undefined;
    if (api.cuCtxCreate_v2(&context, 0, device) != 0) return error.CudaContextFailed;

    const size: usize = 1048576;

    var p = try Tensor.init(allocator, &api, size);
    defer p.deinit(allocator);

    var g = try Tensor.init(allocator, &api, size);
    defer g.deinit(allocator);

